function validate([n, relations, time]) {
  if (!Number.isInteger(n) || n < 1 || n > 50000) return 'n must be between 1 and 50000.';
  if (!Array.isArray(relations) || relations.length > Math.min((n * (n - 1)) / 2, 50000)) return 'Too many relations for n.';
  if (!Array.isArray(time) || time.length !== n) return 'time must have exactly n values.';
  if (time.some(t => !Number.isInteger(t) || t < 1 || t > 10000)) return 'Every time is an integer from 1 to 10000.';
  const graph = Array.from({ length: n + 1 }, () => []), indegree = new Array(n + 1).fill(0), seen = new Set();
  for (const pair of relations) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each relation is a pair [prevCourse, nextCourse].';
    const [a, b] = pair;
    if (![a, b].every(c => Number.isInteger(c) && c >= 1 && c <= n)) return 'Courses are numbered 1 to n.';
    if (a === b) return 'A course cannot be its own prerequisite.';
    const key = a * 100000 + b;
    if (seen.has(key)) return 'Each relation may appear only once.';
    seen.add(key);
    graph[a].push(b);
    indegree[b]++;
  }
  const queue = [];
  for (let c = 1; c <= n; c++) if (indegree[c] === 0) queue.push(c);
  for (let h = 0; h < queue.length; h++) for (const b of graph[queue[h]]) if (--indegree[b] === 0) queue.push(b);
  if (queue.length !== n) return 'The relations must not form a cycle.';
  return null;
}

