function minimumTime(n, relations, time) {
  // Relax every edge n times: after round k, chains of k prerequisites have their true finish time.
  const finish = [0, ...time];
  for (let round = 0; round < n; round++) {
    let changed = false;
    for (const [a, b] of relations) {
      if (finish[a] + time[b - 1] > finish[b]) { finish[b] = finish[a] + time[b - 1]; changed = true; }
    }
    if (!changed) break;
  }
  return Math.max(...finish);
}

