function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 8);
  // A random order of the courses; edges only go forward in it, so the graph is acyclic.
  const order = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  const seen = new Set(), relations = [];
  const add = (i, j) => { const key = order[i] * 100000 + order[j]; if (!seen.has(key)) { seen.add(key); relations.push([order[i], order[j]]); } };
  const style = rand();
  if (large && style < 0.3) {
    for (let i = 0; i + 1 < n; i++) add(i, i + 1);
  } else if (n > 1) {
    const maxEdges = large ? 2000 : (n * (n - 1)) / 2;
    const wanted = Math.floor(rand() * (maxEdges + 1));
    for (let t = 0; t < wanted; t++) {
      const i = Math.floor(rand() * (n - 1));
      const span = large && rand() < 0.7 ? 1 + Math.floor(rand() * 5) : 1 + Math.floor(rand() * (n - 1 - i));
      add(i, Math.min(n - 1, i + span));
    }
  }
  const top = large ? 10000 : rand() < 0.5 ? 5 : 10000;
  const time = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [n, relations, time];
}
